exec(open(WORK/'build2.py').read())
lab=np.load(WORK/'labels.npy'); N=len(lab); Y=np.eye(8)[lab]
F=dict(np.load(WORK/'prep_feats.npz')); A=np.load(WORK/'v2_layer_scales.npy'); abar=A.mean(0)
Xs=np.concatenate([F[p][:,KEEP]*(A[:,k]/abar[k])[:,None] for k,p in enumerate(['m2','m6','m10'])]+[F['c12'][:,KEEP]],1)
def make_folds(seed):
    rng=np.random.RandomState(seed); fo=np.zeros(N,int)
    for c in range(8):
        idx=np.where(lab==c)[0]; rng.shuffle(idx); fo[idx]=np.arange(len(idx))%5
    return fo
lams=[50,100,150,250,400,700]
res={('std',l):[] for l in lams}; res.update({('raw',l):[] for l in [1,3,10,30]})
for seed in range(1,6):
    fo=make_folds(seed)
    for mode in ['std','raw']:
        Ks=[]
        for f in range(5):
            tr=fo!=f; te=~tr
            mu=Xs[tr].mean(0); sd=(Xs[tr].std(0)+1e-6) if mode=='std' else np.ones(Xs.shape[1])
            Z=(Xs[tr]-mu)/sd; Ze=(Xs[te]-mu)/sd; Ks.append((Z@Z.T,Ze@Z.T,tr,te))
        for lam in (lams if mode=='std' else [1,3,10,30]):
            o=np.zeros((N,8))
            for K,Ke,tr,te in Ks:
                al=np.linalg.solve(K+lam*np.eye(len(K)),Y[tr]-Y[tr].mean(0)); o[te]=Ke@al
            res[(mode,lam)].append((o.argmax(1)==lab).mean())
for k,v in res.items(): print(k, np.round(np.mean(v),4), np.round(np.std(v),4))
